// jsmn_init requires a non-NULL parser pointer. The runtime guarantees inputs are non-NULL.
// Initialize the parser state so it can be reused by jsmn_parse.
jsmn_init(parser);
// Track initialization so downstream stubs (e.g., jsmn_parse) can verify correct usage.
FUZZ_SET_ATTR_INT(parser, "initialized", 1);

// Validation summary: parser is taken as input and returned as output (persistent object);
// attribute "initialized" set to enforce the requirement that jsmn_parse must only be called after init.

// Enforce: parser must have been initialized via jsmn_init before parsing a JSON document.
if (FUZZ_GET_ATTR_INT(parser, "initialized") == 0) { FUZZ_BAIL(); }

// Generate a random JSON buffer; may contain arbitrary bytes.
std::string js = FUZZ_PARAM_STR();
// Choose a length within [0, js.size()] to exercise partial-buffer paths safely.
size_t len = (size_t)(*FUZZ_PARAM(unsigned int) % (js.size() + 1));

// Randomly decide whether to supply a tokens buffer or pass NULL to exercise the counting/validation path.
bool use_tokens = ((*FUZZ_PARAM(unsigned int) & 1u) != 0);

jsmntok_t *tokens_ptr = nullptr;
unsigned int num_tokens = 0;

if (use_tokens) {
    // Choose a small capacity to explore both success and JSMN_ERROR_NOMEM; cap to keep under 2048 bytes.
    // Each token is small (<= 24 bytes), so up to 128 tokens keeps allocation modest.
    unsigned int cap = (unsigned int)(*FUZZ_PARAM(unsigned int) % 129u); // 0..128
    if (cap > 0) {
        // Allocate a vector to back the token array.
        std::vector<jsmntok_t> token_vec;
        token_vec.resize(cap);
        tokens_ptr = token_vec.data();
        num_tokens = cap;
        // Parse with a non-NULL tokens array.
        int r = jsmn_parse(parser, js.data(), len, tokens_ptr, num_tokens);
        // No assertions on r; negative values are valid error codes per API. We just exercise the code paths.
        (void)r;
        // Keep parser as output; token_vec is ephemeral and intentionally not returned.
    } else {
        // cap == 0: Exercise zero-capacity path with a NULL pointer and num_tokens == 0.
        tokens_ptr = nullptr;
        num_tokens = 0u;
        int r = jsmn_parse(parser, js.data(), len, tokens_ptr, num_tokens);
        (void)r;
    }
} else {
    // No tokens requested: tokens == NULL and num_tokens is ignored.
    int r = jsmn_parse(parser, js.data(), len, nullptr, 0u);
    (void)r;
}

// Validation summary: Ensures parser was initialized; provides valid js/len; explores both NULL and non-NULL tokens
// paths, including zero-capacity; parser is preserved and returned as an output object.

// Construct a new jsmn_parser and initialize it via the official API.
// No inputs required; we return a ready-to-use parser instance.

// Allocate storage on the heap so the fuzzer runtime can manage the lifetime.
jsmn_parser *parser = new jsmn_parser();

// Per API: parser must be non-NULL before calling jsmn_init (guaranteed here).
jsmn_init(parser);

// Track that the parser has been initialized so downstream stubs (e.g., jsmn_parse) can enforce correct usage.
FUZZ_SET_ATTR_INT(parser, "initialized", 1);

// Validation summary: Allocates a non-NULL parser, initializes it using jsmn_init, and marks it initialized for
// subsequent API calls; ownership is transferred to the fuzzer runtime via outputs.

