import random
import string
from typing import List

# JSON generation focused on producing valid and interesting inputs for jsmn_parse.
# Goals:
# - Produce a wide variety of valid JSON values: objects, arrays, strings, numbers, booleans, null
# - Include nested structures and varied whitespace
# - Include edge-case strings: escapes, unicode, long strings, empty strings
# - Include numbers with different magnitudes and formats (ints, floats, exponents, negatives)
# - Sometimes produce concatenations or leading/trailing data where partial lengths (len) expose PART errors
# - Keep total size <= 4096 bytes
# - Deterministic for a given seed while still varied

MAX_SIZE = 4096

WHITESPACE = [" ", "\t", "\n", "\r"]

ESCAPES = [
    "\\\"",  # escaped quote
    "\\\\",  # backslash
    "\\/",    # solidus
    "\\b",
    "\\f",
    "\\n",
    "\\r",
    "\\t",
]

# Some Unicode escapes; jsmn does not unescape, but they are valid JSON sequences
UNICODE_ESC = [
    "\\u0000", "\\u0001", "\\u001F", "\\u007F", "\\u00A9", "\\u20AC", "\\uD834", "\\uDE00"
]

# A set of common property names and literals to encourage token variety
COMMON_KEYS = [
    "id", "name", "value", "enabled", "count", "items", "data", "_", "", "long_key_name",
]

COMMON_STRINGS = [
    "", "a", "A quick brown fox", "line1\nline2", "tab\tsep", "quote\"here", "unicode-€",
]

COMMON_NUMBERS = [
    "0", "1", "-1", "123", "-999999", "3.14159", "-0.001", "1e10", "-2E-3", "0.0", "1E+2"
]

BOOL_NULL = ["true", "false", "null"]


def rnd_ws(r: random.Random) -> str:
    # random whitespace sequence
    return "".join(r.choices(WHITESPACE, k=r.randint(0, 4)))


def gen_string(r: random.Random, target_len: int | None = None) -> str:
    # Generate a JSON string literal with escapes and unicode
    parts: List[str] = []
    # Choose a base corpus sometimes
    if r.random() < 0.5:
        parts.append(r.choice(COMMON_STRINGS))
    # Add random characters
    extra_len = r.randint(0, 40) if target_len is None else max(0, target_len - len(parts[0]) if parts else target_len)
    alphabet = string.ascii_letters + string.digits + " _-.,:;[]{}()"  # safe visible set
    for _ in range(extra_len):
        p = r.random()
        if p < 0.12:
            parts.append(r.choice(ESCAPES))
        elif p < 0.18:
            parts.append(r.choice(UNICODE_ESC))
        else:
            parts.append(r.choice(alphabet))
    # Occasionally create very long strings, but keep limits
    if target_len is None and r.random() < 0.1:
        long_len = r.randint(100, 800)
        parts.append("x" * long_len)
    s = "".join(parts)
    # Ensure we escape quotes and backslashes properly inside JSON string literal
    s = s.replace("\\", "\\\\").replace("\"", "\\\"")
    return '"' + s + '"'


def gen_number(r: random.Random) -> str:
    if r.random() < 0.5:
        return r.choice(COMMON_NUMBERS)
    # Construct random numeric forms
    neg = '-' if r.random() < 0.3 else ''
    if r.random() < 0.5:
        # integer
        n = str(r.randint(0, 10**9))
        # avoid leading zeros unless zero
        if len(n) > 1 and n[0] == '0':
            n = n.lstrip('0') or '0'
        return neg + n
    else:
        # float/exponent
        int_part = str(r.randint(0, 10**6))
        frac_part = ''.join(r.choices(string.digits, k=r.randint(1, 8)))
        txt = neg + int_part + '.' + frac_part
        if r.random() < 0.5:
            e = 'e' if r.random() < 0.5 else 'E'
            sign = r.choice(['', '+', '-'])
            exp = str(r.randint(0, 308))
            txt += e + sign + exp
        return txt


def gen_literal(r: random.Random) -> str:
    return r.choice(BOOL_NULL)


def gen_value(r: random.Random, depth: int) -> str:
    # Depth control to avoid excessive recursion/size
    if depth <= 0:
        return r.choice([gen_string(r), gen_number(r), gen_literal(r)])
    choice = r.random()
    if choice < 0.22:
        return gen_string(r)
    elif choice < 0.44:
        return gen_number(r)
    elif choice < 0.55:
        return gen_literal(r)
    elif choice < 0.8:
        return gen_array(r, depth - 1)
    else:
        return gen_object(r, depth - 1)


def gen_array(r: random.Random, depth: int) -> str:
    n = r.randint(0, 12)
    elems = []
    for _ in range(n):
        elems.append(rnd_ws(r) + gen_value(r, depth) + rnd_ws(r))
    return '[' + (','.join(elems)) + ']'


def gen_key(r: random.Random) -> str:
    # Use common keys or generated strings (without quotes) then quote them
    if r.random() < 0.6:
        base = r.choice(COMMON_KEYS)
    else:
        base = ''.join(r.choices(string.ascii_letters + string.digits + '_- ', k=r.randint(0, 16)))
    base = base.replace("\\", "\\\\").replace("\"", "\\\"")
    return '"' + base + '"'


def gen_object(r: random.Random, depth: int) -> str:
    n = r.randint(0, 12)
    # ensure some duplicates and ordering variances
    keys = [gen_key(r) for _ in range(n)]
    items = []
    for k in keys:
        v = gen_value(r, depth)
        items.append(rnd_ws(r) + k + rnd_ws(r) + ':' + rnd_ws(r) + v + rnd_ws(r))
    return '{' + (','.join(items)) + '}'


def gen_document(r: random.Random) -> str:
    # Top-level could be any JSON value; occasionally multiple JSONs concatenated
    depth = r.randint(1, 5)
    doc = gen_value(r, depth)
    # Occasionally wrap with leading/trailing whitespace
    if r.random() < 0.8:
        doc = rnd_ws(r) + doc + rnd_ws(r)
    # Occasionally append another value to allow partial-len exploration
    if r.random() < 0.25:
        more = gen_value(r, r.randint(0, 3))
        sep_ws = rnd_ws(r)
        doc = doc + sep_ws + more
    return doc


def maybe_truncate_for_partial(r: random.Random, data: bytes) -> bytes:
    # In the fuzzer stub, len is chosen within [0, size]; our generator only supplies the buffer.
    # To exercise PART paths deterministically sometimes, we can append an extra unfinished structure
    # or leave buffer as-is. But we must keep it valid JSON overall. We'll keep as-is here.
    return data


def clamp_size(b: bytes) -> bytes:
    if len(b) <= MAX_SIZE:
        return b
    # try to cut at a boundary (newline or space or comma or brace) to maintain validity best-effort
    boundary_chars = '\n \t,]}'
    cutpoints = [i for i, ch in enumerate(b[:MAX_SIZE][::-1]) if chr(ch) in boundary_chars]
    if cutpoints:
        idx = MAX_SIZE - cutpoints[0] - 1
        return b[:idx]
    return b[:MAX_SIZE]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Build several candidate JSON documents and optionally concatenate with whitespace to vary size and tokens
    pieces: List[str] = []
    # Choose 1-3 documents to allow both single and multiple roots (the stub may pass a partial len)
    count = 1 if r.random() < 0.65 else r.randint(2, 3)
    for _ in range(count):
        pieces.append(gen_document(r))
    join_ws = rnd_ws(r)
    text = join_ws.join(pieces)
    # Ensure we remain under size
    data = text.encode('utf-8', errors='strict')
    data = clamp_size(data)
    data = maybe_truncate_for_partial(r, data)
    return data
